"use client";

import { useMemo, useState, type ReactNode } from "react";
import {
  DataGridBody,
  DataGridHeader,
  DataGridProvider,
  DataGridRoot,
  defineColumns,
} from "@/registry/default/components/data-grid/data-grid";
import { useDataGridFindReplace } from "@/registry/default/components/data-grid-find-replace/data-grid-find-replace";
import { useDataGridHistory } from "@/registry/default/components/data-grid-history/data-grid-history";
import { Button } from "@/components/ui/button";
import { generateDemoRows, type DemoRow } from "./demo-data";

const columns = defineColumns<DemoRow>()([
  { id: "name", header: "Name", accessorKey: "name", type: "text", width: 160, flex: 2 },
  { id: "email", header: "Email", accessorKey: "email", type: "text", width: 200, flex: 2 },
  { id: "role", header: "Role", accessorKey: "role", type: "text", width: 110, flex: 1 },
  { id: "age", header: "Age", accessorKey: "age", type: "number", width: 80, flex: 1 },
] as const);

export default function DataGridFindReplaceDemo(): ReactNode {
  const [rows, setRows] = useState<readonly DemoRow[]>(() => generateDemoRows(200));
  const findReplace = useDataGridFindReplace();
  const history = useDataGridHistory<DemoRow>();
  const plugins = useMemo(() => [history.plugin, findReplace.plugin], [history.plugin, findReplace.plugin]);

  return (
    <div className="flex flex-col gap-2">
      <div className="flex items-center gap-2">
        <Button type="button" size="sm" variant="outline" onClick={() => findReplace.open()}>
          Find and replace
        </Button>
        <Button type="button" size="sm" variant="outline" disabled={!history.canUndo} onClick={history.undo}>
          Undo
        </Button>
        <p className="m-0 text-sm text-muted-foreground">Press Ctrl+H inside the grid to open the panel.</p>
      </div>
      <DataGridProvider data={rows} columns={columns} getRowId={(row) => row.id} plugins={plugins} onDataChange={setRows}>
        <DataGridRoot className="h-[360px]">
          <DataGridHeader />
          <DataGridBody />
        </DataGridRoot>
      </DataGridProvider>
    </div>
  );
}

/** Deterministic LCG so SSR/CSR markup match without Math.random(); shared across example rows. */
function createSeededLcg(seed: number) {
  let state = seed;
  return () => {
    state = (state * 1103515245 + 12345) & 0x7fffffff;
    return state / 0x7fffffff;
  };
}

export type DemoRow = {
  id: string;
  name: string;
  email: string;
  age: number;
  active: boolean;
  role: string;
  joined: string;
  score: number;
};

const ROLES = ["Admin", "User", "Editor", "Viewer", "Manager"] as const;
const ADJECTIVES = ["Eager", "Quick", "Silent", "Bold", "Swift"] as const;
const NOUNS = ["Eagle", "Lion", "Tiger", "Bear", "Wolf"] as const;

/** Generates `count` deterministic demo rows for example previews (seed 42, stable across renders). */
export function generateDemoRows(count: number, seed = 42): DemoRow[] {
  const next = createSeededLcg(seed);
  const rows: DemoRow[] = [];
  for (let i = 0; i < count; i++) {
    rows.push({
      id: `row-${i}`,
      name: `${ADJECTIVES[Math.floor(next() * ADJECTIVES.length)]} ${NOUNS[Math.floor(next() * NOUNS.length)]}`,
      email: `user${i}@example.com`,
      age: Math.floor(next() * 50) + 18,
      active: next() > 0.5,
      role: ROLES[Math.floor(next() * ROLES.length)]!, // ROLES is a fixed non-empty literal array
      joined: `${2020 + Math.floor(next() * 5)}-${String(Math.floor(next() * 12) + 1).padStart(2, "0")}-${String(Math.floor(next() * 28) + 1).padStart(2, "0")}`,
      score: Math.floor(next() * 100),
    });
  }
  return rows;
}
